/**
 * Comics knowledge base (Phase 7 foundation).
 *
 * Every entry records its evidence status, separating verified facts from interpretations,
 * theories and uncertain information. The built-in seed only contains identity data (names,
 * common FR/EN aliases, kind, publisher) — no plot claims, quotes or dates — and is marked
 * `curated` (editorially reviewed, not yet linked to a citable source). Users and future source
 * connectors add `verified` entries with explicit sources. Nothing here is generated by a model.
 */

export type EntityKind = 'character' | 'team' | 'publisher' | 'event' | 'series' | 'place' | 'creator' | 'concept';
export type EvidenceStatus = 'verified' | 'curated' | 'interpretation' | 'theory' | 'uncertain';

export interface KnowledgeEntry {
  id: string;
  name: string;
  kind: EntityKind;
  aliases: string[];
  publisher?: string;
  status: EvidenceStatus;
  sources?: { title: string; url?: string }[];
}

const C = (id: string, name: string, kind: EntityKind, publisher: string | undefined, aliases: string[] = []): KnowledgeEntry => ({ id, name, kind, publisher, aliases, status: 'curated' });

